'use strict';
const $ = s => document.querySelector(s), board = $('#board'), inventory = $('#inventory');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
let sharedCraft = false;
const BASE = ['Water', 'Fire', 'Wind', 'Earth'], STORAGE = 'wondercraft-v1';
let state = { unlocked: [...BASE], favorites: [], journal: [], completedDays: [], sound: false };
try { const s = JSON.parse(localStorage.getItem(STORAGE)); if (s && Array.isArray(s.unlocked)) { s.journal = restoreInventions(s.journal); state = { ...state, ...s, unlocked: [...new Set([...BASE, ...s.unlocked.filter(n => ELEMENTS[n])])], favorites: (s.favorites || []).filter(n => ELEMENTS[n]), journal: (s.journal || []).filter(r => ELEMENTS[r.result] && ELEMENTS[r.a] && ELEMENTS[r.b]), completedDays: Array.isArray(s.completedDays) ? s.completedDays : [] }; } } catch { }
let tiles = [], nextId = 1, history = [], selected = null, filter = 'all', alphabetical = false, drag = null, toastTimer, audioContext, busy = false;
function save() { try { localStorage.setItem(STORAGE, JSON.stringify(state)); $('#save-status').textContent = '● Saved on this device'; } catch { $('#save-status').textContent = '● Session only'; } }
const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };
const goals = ['Rainbow', 'Butterfly', 'Sailboat', 'Moon', 'Tea', 'Snowman', 'Star', 'Garden', 'Glass', 'Forest', 'Sunset', 'Ocean', 'Bread', 'Bird'];
function dailyGoal() { const hash = [...today()].reduce((a, c) => a * 31 + c.charCodeAt(0), 0) >>> 0; return goals[hash % goals.length]; }
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 3000); }
function sound(newItem = false) { if (!state.sound) return; try { audioContext ||= new (window.AudioContext || window.webkitAudioContext)(); audioContext.resume(); (newItem ? [523, 659, 784, 1046] : [440, 554]).forEach((hz, i) => { const o = audioContext.createOscillator(), g = audioContext.createGain(), t = audioContext.currentTime + i * .085; o.type = 'sine'; o.frequency.value = hz; g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(.065, t + .01); g.gain.exponentialRampToValueAtTime(.001, t + .28); o.connect(g); g.connect(audioContext.destination); o.start(t); o.stop(t + .3); }); } catch { } }
function particleBurst(x, y) { if (matchMedia('(prefers-reduced-motion: reduce)').matches) return; for (let i = 0; i < 22; i++) { const p = document.createElement('i'); p.className = 'particle'; p.style.cssText = `left:${x}px;top:${y}px;background:${['#a7bc7a', '#e9bf6b', '#88b8b9', '#c6a5c8'][i % 4]};--dx:${(Math.random() - .5) * 240}px;--dy:${(Math.random() - .6) * 210}px`; $('#particles').append(p); setTimeout(() => p.remove(), 900); } }
function makeButton(name, cls = '') { const e = ELEMENTS[name], b = document.createElement('button'); b.className = 'element ' + cls; b.dataset.name = name; b.setAttribute('aria-label', `${name}${cls ? ' on workspace' : ''}`); const emoji = document.createElement('span'); emoji.className = 'emoji'; emoji.textContent = e.emoji; const label = document.createElement('span'); label.textContent = name; b.append(emoji, label); if (state.favorites.includes(name)) { const star = document.createElement('span'); star.className = 'favorite-dot'; star.textContent = '★'; b.append(star); } return b; }
function renderInventory() { inventory.replaceChildren(); let names = state.unlocked.filter(n => n.toLowerCase().includes($('#search').value.toLowerCase()) && (filter !== 'new' || !BASE.includes(n)) && (filter !== 'favorites' || state.favorites.includes(n))); if (alphabetical) names.sort((a, b) => a.localeCompare(b)); else names = [...names.filter(n => BASE.includes(n)), ...names.filter(n => !BASE.includes(n)).reverse()]; for (const n of names) { const b = makeButton(n); b.addEventListener('pointerdown', e => beginDrag(e, n)); b.addEventListener('click', e => { if (e.detail === 0) addOrCombine(n); }); b.addEventListener('contextmenu', e => { e.preventDefault(); showElement(n); }); inventory.append(b); } if (!names.length) { const p = document.createElement('p'); p.className = 'empty-list'; p.textContent = filter === 'favorites' ? 'Your favorite little things live here. Right-click a tile or open a field note to save one.' : 'Nothing here yet. A little experimenting might change that.'; inventory.append(p); } $('#count').textContent = state.unlocked.length; const discoveries = state.unlocked.length - 4, steps = [5, 15, 30, 60, 100, 150], target = steps.find(n => n > discoveries) || 150; $('#rank').textContent = discoveries < 5 ? 'CURIOUS SOUL' : discoveries < 15 ? 'SPARK FINDER' : discoveries < 30 ? 'WORLD MAKER' : discoveries < 60 ? 'WONDER SEEKER' : 'MASTER EXPLORER'; $('#progress-label').textContent = `${discoveries} / ${target} discoveries`; $('#progress').style.width = Math.min(100, discoveries / target * 100) + '%'; $('#journal-count').textContent = state.journal.length + ' recipes ↗'; $('#daily-name').textContent = (state.completedDays.includes(today()) ? '✓ ' : 'Find a ') + dailyGoal(); $('#sound').style.background = state.sound ? '#e6eccd' : ''; $('#sound').setAttribute('aria-label', state.sound ? 'Mute sounds' : 'Enable sounds'); }
function snapshot() { history.push(tiles.map(({ id, name, x, y }) => ({ id, name, x, y }))); if (history.length > 25) history.shift(); }
function bounds(x, y) { return { x: Math.max(4, Math.min(board.clientWidth - 225, x)), y: Math.max(115, Math.min(board.clientHeight - 90, y)) }; }
function addTile(name, x, y) { if (tiles.length >= 45) { toast('A busy little universe! Clear a little space first.'); return null; } const p = bounds(x ?? board.clientWidth * .4 + (Math.random() - .5) * 100, y ?? board.clientHeight * .5 + (Math.random() - .5) * 90); const t = { id: nextId++, name, ...p }; tiles.push(t); renderBoard(); return t; }
function renderBoard() { board.replaceChildren(); for (const t of tiles) { const b = makeButton(t.name, 'tile' + (selected === t.id ? ' selected' : '')); b.style.left = t.x + 'px'; b.style.top = t.y + 'px'; b.dataset.id = t.id; b.addEventListener('pointerdown', e => beginDrag(e, t.name, t)); b.addEventListener('click', e => { if (e.detail === 0) selectTile(t); }); b.addEventListener('contextmenu', e => { e.preventDefault(); showElement(t.name); }); board.append(b); } $('#welcome').style.opacity = tiles.length ? '0' : '1'; $('#welcome').style.visibility = tiles.length ? 'hidden' : 'visible'; $('#selection').hidden = !selected; if (selected) { const t = tiles.find(t => t.id === selected); if (t) $('#selection-text').textContent = `${ELEMENTS[t.name].emoji} ${t.name} + choose another element`; else clearSelection(); } }
function clearSelection() { selected = null; $('#selection').hidden = true; board.querySelectorAll('.selected').forEach(b => b.classList.remove('selected')); }
function selectTile(t) { if (busy) return; if (selected && selected !== t.id) { const other = tiles.find(x => x.id === selected); clearSelection(); combine(other, t); } else if (selected === t.id) { clearSelection(); } else { selected = t.id; renderBoard(); } }
function addOrCombine(name) { if (busy) return; if (selected) { const other = tiles.find(t => t.id === selected); clearSelection(); snapshot(); const t = addTile(name, other.x + 40, other.y + 60); if (t) combine(other, t, false); } else { snapshot(); addTile(name); } }
function beginDrag(e, name, tile) { if (e.button !== 0) return; if (busy) { toast('One little spark at a time…'); return; } e.preventDefault(); const rect = e.currentTarget.getBoundingClientRect(); drag = { name, tile, startX: e.clientX, startY: e.clientY, offsetX: e.clientX - rect.left, offsetY: e.clientY - rect.top, moved: false, source: e.currentTarget, original: tiles.map(t => ({ ...t })) }; }
window.addEventListener('pointermove', e => { if (!drag) return; if (!drag.moved && Math.hypot(e.clientX - drag.startX, e.clientY - drag.startY) < 7) return; e.preventDefault(); if (!drag.moved) { drag.moved = true; drag.ghost = makeButton(drag.name, 'dragging'); drag.ghost.style.position = 'fixed'; drag.ghost.style.zIndex = '100'; drag.ghost.style.pointerEvents = 'none'; document.body.append(drag.ghost); if (drag.tile) drag.source.style.opacity = '.2'; } drag.ghost.style.left = e.clientX - drag.offsetX + 'px'; drag.ghost.style.top = e.clientY - drag.offsetY + 'px'; board.querySelectorAll('.target').forEach(b => b.classList.remove('target')); drag.target = tiles.find(t => t.id !== drag.tile?.id && pointInTile(e.clientX, e.clientY, t)); if (drag.target) board.querySelector(`[data-id="${drag.target.id}"]`)?.classList.add('target'); }, { passive: false });
function pointInTile(x, y, t) { const b = board.querySelector(`[data-id="${t.id}"]`); if (!b) return false; const r = b.getBoundingClientRect(); if (x > r.left - 22 && x < r.right + 22 && y > r.top - 22 && y < r.bottom + 22) return true; if (drag?.ghost) { const g = drag.ghost.getBoundingClientRect(); const overlap = Math.max(0, Math.min(g.right, r.right) - Math.max(g.left, r.left)) * Math.max(0, Math.min(g.bottom, r.bottom) - Math.max(g.top, r.top)); return overlap > Math.min(g.width * g.height, r.width * r.height) * .18; } return false; }
window.addEventListener('pointerup', e => { if (!drag) return; const d = drag; drag = null; d.ghost?.remove(); d.source.style.opacity = ''; board.querySelectorAll('.target').forEach(b => b.classList.remove('target')); if (!d.moved) { if (d.tile) selectTile(d.tile); else addOrCombine(d.name); return; } const r = board.getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) return; clearSelection(); snapshot(); let t = d.tile; if (!t) t = addTile(d.name, e.clientX - r.left - d.offsetX, e.clientY - r.top - d.offsetY); if (!t) return; if (d.target) combine(t, d.target, false); else { Object.assign(t, bounds(e.clientX - r.left - d.offsetX, e.clientY - r.top - d.offsetY)); renderBoard(); } });
