async function combine(a, b, takeSnapshot = true) { if (busy || !a || !b || a.id === b.id) return; if (takeSnapshot) snapshot(); busy = true; board.querySelector(`[data-id="${a.id}"]`)?.classList.add('busy'); board.querySelector(`[data-id="${b.id}"]`)?.classList.add('busy'); try { const prior = state.journal.find(r => pairKey(r.a, r.b) === pairKey(a.name, b.name)); const result = prior && ELEMENTS[prior.result] ? { ...ELEMENTS[prior.result], source: prior.source, isNew: false } : await resolveRecipe(a.name, b.name); if (!result) { renderBoard();[a, b].forEach(t => board.querySelector(`[data-id="${t.id}"]`)?.classList.add('shake')); toast('No spark this time. Try a different pair.'); return; } const isNew = !state.unlocked.includes(result.name); $('#last-recipe').textContent = `${ELEMENTS[a.name].emoji} ${a.name} + ${ELEMENTS[b.name].emoji} ${b.name} → ${result.emoji} ${result.name}`; $('#last-recipe').hidden = false; if (isNew) state.unlocked.push(result.name); if (!state.journal.some(r => pairKey(r.a, r.b) === pairKey(a.name, b.name))) state.journal.push({ a: a.name, b: b.name, result: result.name, emoji: result.emoji, family: result.family, source: result.source, date: today() }); const x = (a.x + b.x) / 2, y = (a.y + b.y) / 2; tiles = tiles.filter(t => t.id !== a.id && t.id !== b.id); addTile(result.name, x, y); sound(isNew); if (!isNew) toast(`${result.emoji} ${result.name} — rediscovered. Try it with something else!`); if (isNew) { const r = board.getBoundingClientRect(); particleBurst(r.left + x + 55, r.top + y + 20); toast(result.isNew && result.source === 'model' ? `${result.emoji} ${result.name} — first discovery!` : `${result.emoji} ${result.name} — a new little discovery!`); $('#discovery-note').textContent = `✧ ${result.name}. Who knows what comes next?`; } if (result.name === dailyGoal() && !state.completedDays.includes(today())) { state.completedDays.push(today()); toast(`☀ Daily quest complete. ${result.name} is yours!`); } save(); renderInventory(); } catch { toast('That spark got interrupted. Your elements are still here.'); renderBoard(); } finally { busy = false; } }
function hintRecipe() { for (const [key, result] of RECIPES) { const [a, b] = key.split('|'); if (state.unlocked.includes(a) && state.unlocked.includes(b) && !state.unlocked.includes(result)) return { a, b, result }; } return null; }
function modal(html) { $('#modal-body').innerHTML = html; if (!$('#modal').open) $('#modal').showModal(); }
function showElement(name) { const e = ELEMENTS[name]; if (!e) return; const r = state.journal.find(entry => entry.result === name); const badge = e.model ? '<span class="goal-label">✧ Shared discovery</span>' : e.procedural ? '<span class="goal-label">✧ Procedural discovery</span>' : ''; const recipe = r ? `${esc(ELEMENTS[r.a].emoji)} ${esc(r.a)} + ${esc(ELEMENTS[r.b].emoji)} ${esc(r.b)}` : 'One of your four little beginnings.'; modal(`<span class="eyebrow">A PAGE FROM YOUR FIELD NOTES</span><p class="big-emoji">${esc(e.emoji)}</p><h2>${esc(name)}</h2>${badge}<p>${recipe}</p><button class="action" id="favorite-toggle">${state.favorites.includes(name) ? '★ Unfavorite' : '☆ Save as favorite'}</button><button class="action" id="use-element">Put on the desk ↗</button>`); $('#favorite-toggle').onclick = () => { state.favorites = state.favorites.includes(name) ? state.favorites.filter(n => n !== name) : [...state.favorites, name]; save(); renderInventory(); showElement(name); }; $('#use-element').onclick = () => { $('#modal').close(); addOrCombine(name); }; }
$('#first-spark').onclick = () => { snapshot(); const w = board.clientWidth, h = board.clientHeight; addTile('Fire', w * .5 - 140, h * .49); addTile('Water', w * .5 + 20, h * .53); toast('Drop Fire onto Water — or tap one, then the other.'); };
$('#hint').onclick = () => { if (busy) return; const h = hintRecipe(); if (!h) { const options = state.unlocked; for (let i = 0; i < options.length; i++)for (let j = i; j < options.length; j++)if (!state.journal.some(r => pairKey(r.a, r.b) === pairKey(options[i], options[j]))) { snapshot(); addTile(options[i], board.clientWidth * .35, board.clientHeight * .5); addTile(options[j], board.clientWidth * .55, board.clientHeight * .5 + 45); toast('An untried pair. What will you discover?'); return; } toast('Try combining your latest discoveries.'); return; } snapshot(); addTile(h.a, board.clientWidth * .5 - 135, board.clientHeight * .5); addTile(h.b, board.clientWidth * .5 + 20, board.clientHeight * .5 + 35); toast(`What might ${h.a} and ${h.b} become?`); };
$('#undo').onclick = () => { if (busy) return; if (!history.length) { toast('Nothing to undo just yet.'); return; } clearSelection(); tiles = history.pop(); renderBoard(); };
$('#clear').onclick = () => { if (busy) return; if (!tiles.length) return; snapshot(); tiles = []; clearSelection(); renderBoard(); toast('Fresh desk. Your discoveries are safe.'); };
$('#cancel-selection').onclick = clearSelection;
$('#search').oninput = renderInventory;
document.querySelectorAll('[data-filter]').forEach(b => b.onclick = () => { filter = b.dataset.filter; document.querySelectorAll('[data-filter]').forEach(x => x.classList.toggle('active', x === b)); renderInventory(); });
$('#sort').onclick = () => { alphabetical = !alphabetical; $('#sort').textContent = alphabetical ? 'A↓' : '↓↑'; $('#sort').title = alphabetical ? 'Alphabetical order' : 'Newest discoveries first'; renderInventory(); };
$('#sound').onclick = () => { state.sound = !state.sound; save(); renderInventory(); sound(true); };
$('#help').onclick = () => modal(`<span class="eyebrow">WELCOME TO WONDERCRAFT</span><h2>Follow your curiosity.</h2><p>Drag a tile from your collection onto the desk. Drop it onto another tile to see what they become.</p><p>Prefer tapping? Tap a tile on the desk, then choose another tile or an element in your collection. Keyboard users can do the same with Tab and Enter.</p><p>Every discovery stays in your collection. Open Field notes to revisit recipes and favorite your finds. A fresh daily quest appears each day.</p><p class="note">${sharedCraft ? `${RECIPES.size} handcrafted recipes are built in. A new pair is invented once by Gemma and saved on this server, so the next player gets the same result. If Gemma’s free quota runs out, Llama tries.` : `${RECIPES.size} handcrafted recipes are built in. Other pairs use a local word mixer until a Gemma key is added to the server.`} The same saved pair stays the same. Your progress lives in this browser; export a backup from Field notes to keep it.</p>`);
$('#daily').onclick = () => { const name = dailyGoal(), done = state.completedDays.includes(today()); modal(`<span class="eyebrow">TODAY’S LITTLE QUEST · ${today()}</span><p class="big-emoji">${esc(ELEMENTS[name].emoji)}</p><h2>${done ? 'A lovely little find.' : 'Can you make ' + esc(name) + '?'}</h2><span class="goal-label">${done ? '✓ Completed today' : 'Craft it today to collect your daily stamp'}</span><p>${done ? 'Come back tomorrow for a new trail to follow.' : 'Start with your four elements and follow the possibilities. Already have this item? Make it again to complete today’s quest.'}</p><p class="note">${state.completedDays.length} daily ${state.completedDays.length === 1 ? 'stamp' : 'stamps'} collected on this device.</p>`); };
$('#journal').onclick = () => { modal(`<span class="eyebrow">YOUR DISCOVERY JOURNAL</span><h2>Little things you found.</h2><p class="note">${state.unlocked.length - 4} discoveries. ${state.journal.length} recipes. Tap a discovery to favorite it.</p><div id="journal-list"></div><div class="journal-actions"><button id="export">↓ Export progress</button><button id="import">↑ Import progress</button></div>`); const list = $('#journal-list'); if (!state.journal.length) list.innerHTML = '<p>Your story is just beginning. Combine Fire and Water to write your first field note.</p>'; for (const r of [...state.journal].reverse()) { const row = document.createElement('button'); row.className = 'recipe-row'; row.style.cssText = 'display:block;width:100%;background:none;border:0;border-bottom:1px solid #e8ebdf;text-align:left'; row.textContent = `${ELEMENTS[r.a].emoji} ${r.a} + ${ELEMENTS[r.b].emoji} ${r.b} → ${ELEMENTS[r.result].emoji} ${r.result}`; row.onclick = () => showElement(r.result); list.append(row); } $('#export').onclick = () => { const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }), url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = 'wondercraft-progress.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }; $('#import').onclick = () => { const input = document.createElement('input'); input.type = 'file'; input.accept = '.json,application/json'; input.onchange = async () => { try { const s = JSON.parse(await input.files[0].text()); if (!Array.isArray(s.unlocked)) throw Error(); s.journal = restoreInventions(s.journal); if (s.unlocked.some(n => !Object.hasOwn(ELEMENTS, n))) throw Error(); state.unlocked = [...new Set([...state.unlocked, ...s.unlocked])]; if (Array.isArray(s.favorites)) state.favorites = [...new Set([...state.favorites, ...s.favorites.filter(n => ELEMENTS[n])])]; if (Array.isArray(s.journal)) for (const r of s.journal) if (ELEMENTS[r.a] && ELEMENTS[r.b] && inventRecipe(r.a, r.b).name === r.result && !state.journal.some(x => pairKey(x.a, x.b) === pairKey(r.a, r.b))) state.journal.push({ a: r.a, b: r.b, result: r.result, emoji: r.emoji, family: r.family, source: r.source, date: typeof r.date === 'string' ? r.date.slice(0, 10) : today() }); if (Array.isArray(s.completedDays)) state.completedDays = [...new Set([...state.completedDays, ...s.completedDays.filter(d => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d))])]; save(); renderInventory(); $('#modal').close(); toast('Your discoveries are back where they belong.'); } catch { toast('That file doesn’t look like a Wondercraft save.'); } }; input.click(); }; };
$('.modal-close').onclick = () => $('#modal').close(); $('#modal').addEventListener('click', e => { if (e.target === $('#modal')) { const r = $('#modal').getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) $('#modal').close(); } });
window.addEventListener('keydown', e => { if (e.key === '/' && !$('#modal').open && document.activeElement.tagName !== 'INPUT') { e.preventDefault(); $('#search').focus(); } if (e.key === 'Escape') clearSelection(); });
