window.addEventListener('focus', renderInventory);
fetch('/api/health').then(r => r.ok ? r.json() : null).then(h => { if (!h) return; sharedCraft = !!(h.gemma || h.llama); const label = $('#craft-mode'); if (label) label.textContent = sharedCraft ? 'Every pair is a possibility · shared discoveries' : 'Every pair is a possibility · local invention'; }).catch(() => { });
